package com.termux.app.workspace;
import org.json.*;import org.junit.*;import static org.junit.Assert.*;
import java.util.*;import java.util.concurrent.atomic.AtomicBoolean;
import android.app.Application;import org.junit.runner.RunWith;import org.robolectric.RobolectricTestRunner;import org.robolectric.annotation.Config;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28,application=Application.class)
public class LocalAiVideoTest {
 String prepared()throws Exception{JSONArray frames=new JSONArray();for(int i=0;i<3;i++)frames.put(new JSONObject().put("path","/cache/frame-"+i+".jpg").put("requestedTimeMillis",i*1000));return "exit=0\n"+new JSONObject().put("mode","view_video").put("source","/video.mp4").put("durationMillis",2001).put("images",frames);}
 static class Fake implements LocalAiVideo.Model {
  String schemas="original tool schemas",scope="original-chat";int calls;List<JSONArray> messages=new ArrayList<>();List<LocalAiVideo.Attempt> replies=new ArrayList<>();Exception fail;int failAt=-1;
  public String schemas(){return schemas;}public void schemas(String value){schemas=value;}public String scope(){return scope;}public void scope(String value){scope=value;}
  public LocalAiVideo.Attempt infer(JSONArray h,String system,int tokens,String purpose)throws Exception{assertEquals("[]",schemas);assertNotEquals("original-chat",scope);assertEquals(1,h.length());assertTrue(system.contains("No tools"));assertEquals(256,tokens);messages.add(new JSONArray(h.toString()));int index=calls++;if(index==failAt)throw fail;return replies.get(index);}
 }
 void restored(Fake f){assertEquals("original tool schemas",f.schemas);assertEquals("original-chat",f.scope);}
 @Test public void jointAnalysisPreservesAllFramesAndReturnsTextOnlyToolResult()throws Exception{Fake f=new Fake();f.replies.add(new LocalAiVideo.Attempt("Screen changes from A to B","sdk_done",3));String result=LocalAiVideo.analyze(prepared(),"Describe changes",f,(i,n)->{},new AtomicBoolean());restored(f);assertEquals(1,f.calls);assertEquals(3,f.messages.get(0).getJSONObject(0).getJSONArray("media").length());assertEquals(0,LocalAiMedia.attachments(result).length());JSONObject data=new JSONObject(result.substring(7));assertEquals(3,data.getJSONObject("videoAnalysis").getInt("framesAnalyzed"));assertEquals("joint",data.getJSONObject("videoAnalysis").getString("strategy"));assertFalse(data.getBoolean("audioAnalyzed"));assertTrue(result.contains("Screen changes"));}
 @Test public void droppedJointFramesTriggerAllThreeIndividualPasses()throws Exception{Fake f=new Fake();f.replies.add(new LocalAiVideo.Attempt("Only one image seen","sdk_done",1));for(int i=0;i<3;i++)f.replies.add(new LocalAiVideo.Attempt("Frame "+i,"sdk_done",1));List<Integer> progress=new ArrayList<>();String result=LocalAiVideo.analyze(prepared(),"What changes",f,(i,n)->progress.add(i),new AtomicBoolean());restored(f);assertEquals(Arrays.asList(0,1,2,3),progress);assertEquals(4,f.calls);for(int i=1;i<4;i++)assertEquals(1,f.messages.get(i).getJSONObject(0).getJSONArray("media").length());JSONObject analysis=new JSONObject(result.substring(7)).getJSONObject("videoAnalysis");assertEquals("sequential",analysis.getString("strategy"));assertEquals(3,analysis.getJSONArray("observations").length());assertFalse(result.contains("Only one image seen"));}
 @Test public void cancellationAndEngineFailureAlwaysRestoreNormalChatSettings()throws Exception{for(Exception error:new Exception[]{new java.util.concurrent.CancellationException(),new IllegalStateException("engine unavailable")}){Fake f=new Fake();f.failAt=0;f.fail=error;try{LocalAiVideo.analyze(prepared(),"question",f,(i,n)->{},new AtomicBoolean());fail();}catch(Exception expected){assertSame(error,expected);}restored(f);}}
 @Test public void missingSingleFrameAndNativeToolReplyCannotBeReportedAsAnalyzed()throws Exception{Fake f=new Fake();f.replies.add(new LocalAiVideo.Attempt("{\"tool\":\"command\",\"command\":\"bad\"}","native_tool",3));f.replies.add(new LocalAiVideo.Attempt("unconfirmed","sdk_done",0));try{LocalAiVideo.analyze(prepared(),"question",f,(i,n)->{},new AtomicBoolean());fail();}catch(IllegalStateException e){assertTrue(e.getMessage().contains("VIDEO_ANALYSIS_INCOMPLETE"));}restored(f);assertEquals(2,f.calls);}
 @Test public void otherMediaAndUnsupportedResultsNeverStartSubInference()throws Exception{Fake f=new Fake();assertEquals("exit=4\nUNSUPPORTED_VISION",LocalAiVideo.analyze("exit=4\nUNSUPPORTED_VISION","q",f,(i,n)->{},new AtomicBoolean()));String image="exit=0\n{\"mode\":\"view_image\",\"images\":[]}";assertEquals(image,LocalAiVideo.analyze(image,"q",f,(i,n)->{},new AtomicBoolean()));assertEquals(0,f.calls);restored(f);}
 @Test public void compactPreviewKeepsFrameCountsAndOriginalDescriptionsStaySaved()throws Exception{Fake f=new Fake();String longText=new String(new char[1500]).replace('\0','x');f.replies.add(new LocalAiVideo.Attempt(longText,"sdk_done",3));String result=LocalAiVideo.analyze(prepared(),"q",f,(i,n)->{},new AtomicBoolean());String preview=LocalAiListContext.preview(new JSONObject().put("tool","view_video"),result);JSONObject compact=new JSONObject(preview.substring(7));assertFalse(compact.has("fullVideoDescriptions"));assertTrue(compact.getJSONObject("videoAnalysis").getBoolean("descriptionExcerpts"));assertEquals(1500,new JSONObject(result.substring(7)).getJSONArray("fullVideoDescriptions").getJSONObject(0).getString("text").length());assertEquals(3,compact.getJSONObject("videoAnalysis").getInt("framesAnalyzed"));assertEquals(0,LocalAiMedia.attachments(result).length());}
 @Test public void contextOverflowFallsBackButCancellationBetweenFramesStops()throws Exception{Fake f=new Fake();f.failAt=0;f.fail=new IllegalStateException("CONTEXT_TOO_SMALL");f.replies.add(null);f.replies.add(new LocalAiVideo.Attempt("first","sdk_done",1));AtomicBoolean cancel=new AtomicBoolean();try{LocalAiVideo.analyze(prepared(),"q",f,(i,n)->{if(i==2)cancel.set(true);},cancel);fail();}catch(java.util.concurrent.CancellationException expected){}restored(f);}
}
